// =========================================================================
// UNIFORMS
// =========================================================================

uniform sampler2D uPreviousFrame; // Input texture
uniform vec2 uResolution;
uniform vec2 uMouse;

// --- SETTINGS ---
uniform float uMaxBlur;     // 20.0 (How blurry the edges get)
uniform float uFalloff;     // 0.8  (0.2 = Tight circle, 1.0 = Huge soft area)
uniform float uDirectionAngle; // New uniform for blur direction in radians
uniform int uSamples;

// =========================================================================
// MAIN SHADER
// =========================================================================

void mainImage(const in vec4 inputColor, const in vec2 uv, out vec4 outputColor) {

    vec2 pixel = 1.0 / uResolution;

    // ---------------------------------------------------------------------
    // 1. CALCULATE FOCUS MASK
    // ---------------------------------------------------------------------

    // Fix aspect ratio so the focus field is round, not squashed
    vec2 aspect = vec2(uResolution.x / uResolution.y, 1.0);

    // Calculate distance from mouse to current pixel
    float dist = distance(uv * aspect, uMouse * aspect);

    // Create the gradient.
    // Near mouse (0.0) -> Mask is 0.0
    // Far away  (1.0) -> Mask is 1.0
    // pow(dist, ...) makes the "Sharp" center area larger and softer.
    float blurAmount = smoothstep(0.0, uFalloff, dist);

    // ---------------------------------------------------------------------
    // 2. DIRECTIONAL BLUR LOOP
    // ---------------------------------------------------------------------

    // Calculate blur direction based on uDirectionAngle
    vec2 direction = vec2(cos(uDirectionAngle), sin(uDirectionAngle));

    // Calculate how far to spread the pixels based on distance from mouse
    float strength = blurAmount * uMaxBlur;

    vec4 accumulatedColor = vec4(0.0);
    float totalWeight = 0.0;

    // We center the blur on the pixel (-0.5 to 0.5)
    for (int i = 0; i <= uSamples; i++) {

        // Normalized progress from -0.5 to 0.5
        float p = (float(i) / float(uSamples)) - 0.5;

        // Calculate offset: Direction * Strength * Progress
        vec2 offset = direction * strength * pixel * p;

        // Sample the image
        // We use a weighting curve (1.0 - abs(p)) so the center pixels count more.
        // This makes the blur smoother and less "ghostly".
        float weight = 1.0 - abs(p);

        accumulatedColor += texture2D(uPreviousFrame, uv + offset) * weight;
        totalWeight += weight;
    }

    // ---------------------------------------------------------------------
    // 3. OUTPUT
    // ---------------------------------------------------------------------

    outputColor = accumulatedColor / totalWeight;
}
